<script setup>
import { computed, ref } from 'vue'
import { monthBounds, daysBetween, addDays, ganttSegments, itemColor, itemStatus, isAnomaly, startDate, isCompleted } from '../calendarDates.js'
const props = defineProps({ month: String, today: String, items: { type: Array, default: () => [] }, showCompleted: Boolean, disabled: Boolean })
defineEmits(['open'])
const scale = ref('day')
const bounds = computed(() => monthBounds(props.month))
const days = computed(() => Array.from({ length: daysBetween(bounds.value.first,bounds.value.last) + 1 },(_,i)=>addDays(bounds.value.first,i)))
const width = computed(() => scale.value === 'day' ? 36 : 22)
const rows = computed(() => props.items.filter(item => item.due_date && (!isCompleted(item) || props.showCompleted) && (isAnomaly(item) ? item.due_date >= bounds.value.first && item.due_date <= bounds.value.last : ganttSegments(item,props.today,bounds.value.first,bounds.value.last).length)))
function barStyle(item, part) { return { left: `${daysBetween(bounds.value.first,part.from) * width.value}px`, width: `${(daysBetween(part.from,part.to) + 1) * width.value}px`, backgroundColor: part.overdue ? 'transparent' : itemColor(item,props.today), borderColor: itemColor(item,props.today) } }
</script>
<template><section aria-label="甘特图" class="gantt"><div class="scale"><span>时间刻度</span><button :aria-pressed="scale === 'day'" @click="scale='day'">日</button><button :aria-pressed="scale === 'week'" @click="scale='week'">周</button><span class="hint">左右滚动查看时间；点击横条打开详情。</span></div><p v-if="!rows.length" class="hint">本月没有可展示的排期事件。</p><div v-else class="scroll" tabindex="0" aria-label="甘特时间轴，可左右滚动"><div class="chart" :style="{ width: `${160 + days.length * width}px` }"><div class="head"><div class="name">事件 / 开始 → DDL</div><div class="axis" :style="{ width: `${days.length * width}px` }"><span v-for="(date,i) in days" :key="date" :style="{ width: `${width}px` }">{{ scale === 'day' || i === 0 || i % 7 === 0 ? date.slice(5) : '' }}</span></div></div><div v-for="item in rows" :key="item.id" class="row"><button class="name event-name" :disabled="disabled" @click="$emit('open',item)"><span>{{ item.title }}</span><small>{{ startDate(item) }} → {{ item.due_date }}</small><small>{{ itemStatus(item,today) }}</small></button><div class="track" :style="{ width: `${days.length * width}px`, backgroundSize: `${width}px 100%` }"><div v-if="today >= bounds.first && today <= bounds.last" class="today-line" :style="{ left: `${daysBetween(bounds.first,today) * width}px` }" title="今天"></div><button v-for="(part,i) in ganttSegments(item,today,bounds.first,bounds.last)" :key="i" class="bar" :class="{ extension: part.overdue }" :style="barStyle(item,part)" :disabled="disabled" :aria-label="`${item.title}，${part.overdue ? '逾期延伸' : '计划区间'}，${part.from} 至 ${part.to}，${itemStatus(item,today)}`" @click="$emit('open',item)"><span v-if="part.overdue">逾期</span></button><button v-if="isAnomaly(item)" class="anomaly" :style="{ left: `${daysBetween(bounds.first,item.due_date) * width}px`, backgroundColor: itemColor(item,today), borderColor: isCompleted(item) ? itemColor(item,today) : '#450A0A' }" :disabled="disabled" :aria-label="`${item.title}：截止日早于开始日，请核对日期`" @click="$emit('open',item)">!</button></div></div></div></div></section></template>
<style scoped>.gantt{min-width:0;width:100%}.scale{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px;margin-bottom:12px}.scale button{padding:4px 12px;min-height:28px}.scale button[aria-pressed=true]{background:#edf2ff;color:var(--brand);border-color:#adc2f1}.scroll{overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:7px;max-height:540px}.chart{min-width:0}.head,.row{display:flex;border-bottom:1px solid var(--line)}.head{position:sticky;top:0;z-index:4;background:#f3f6fc}.name{flex:0 0 160px;width:160px;position:sticky;left:0;z-index:3;padding:10px;background:#f8fafd;border-right:1px solid var(--line);font-size:12px}.event-name{border-radius:0;border-top:0;border-bottom:0;border-left:0;align-items:flex-start;justify-content:center;flex-direction:column;gap:4px;text-align:left}.event-name span{overflow-wrap:anywhere;max-width:100%;font-size:12px}.event-name small{color:var(--muted);font-size:9px}.axis{display:flex;flex-shrink:0}.axis span{font-size:9px;flex-shrink:0;text-align:center;padding-top:12px;border-right:1px solid var(--line)}.track{position:relative;flex-shrink:0;min-height:78px;background-image:linear-gradient(to right,#e5eaf2 1px,transparent 1px)}.bar{position:absolute;top:24px;height:26px;min-height:26px;border-width:1px;border-style:solid;border-radius:3px;padding:0;font-size:9px;color:#450a0a;overflow:hidden}.bar.extension{border:2px dashed;top:25px;height:24px;min-height:24px}.bar:hover{filter:brightness(.92)}.today-line{position:absolute;top:0;bottom:0;border-left:2px solid #3159cb;pointer-events:none;z-index:2}.anomaly{position:absolute;top:23px;min-height:28px;width:25px;padding:0;color:#fff;background:#7f1d1d;border:2px solid #450a0a}.hint{margin:0}</style>
